CREATE TABLE MapeamentosDePara ( Id INT AUTO_INCREMENT PRIMARY KEY, TextoOriginal VARCHAR(255) NOT NULL, ContaPadraoId INT NOT NULL, EmpresaId INT NULL, CONSTRAINT FK_MapeamentosDePara_ContaPadrao FOREIGN KEY (ContaPadraoId) REFERENCES ContasPadrao(Id), CONSTRAINT FK_MapeamentosDePara_Empresa FOREIGN KEY (EmpresaId) REFERENCES Empresas(Id), UNIQUE KEY UQ_Texto_Empresa (TextoOriginal, EmpresaId) );
